//! Read-only integration: native remote file read, offscreen frame, input,
//! resize and private-session cleanup. Never starts an agent or changes a chat.
#[allow(dead_code)]#[path="../src/document_session.rs"]mod document_session;
use serde_json::{json,Value};use std::sync::{Mutex,mpsc};
static EVENTS:Mutex<Option<mpsc::Sender<(String,Value)>>>=Mutex::new(None);
fn emit(kind:&str,v:Value){if let Some(tx)=EVENTS.lock().unwrap().as_ref(){let _=tx.send((kind.into(),v));}}
fn main(){let args=std::env::args().collect::<Vec<_>>();let(tx,rx)=mpsc::channel();*EVENTS.lock().unwrap()=Some(tx);let manager=document_session::start_with(std::fs::canonicalize("bin/omarchy-t3-client").unwrap());let id=uuid::Uuid::new_v4().to_string();manager.send(json!({"op":"document-open","requestId":id,"environment":args[1],"thread":args[2],"path":args[3],"theme":{"appearance":"dark","variables":{"--background":"#111111","--foreground":"#bbbbbb","--card":"#191919","--secondary":"#242424","--accent":"#e99700","--font-sans":"sans-serif","--border":"#444444"}}}));let mut first=String::new();let mut frames=0;let mut resized=false;let until=std::time::Instant::now()+std::time::Duration::from_secs(15);
 while std::time::Instant::now()<until{let(kind,v)=rx.recv_timeout(std::time::Duration::from_secs(5)).unwrap();if kind=="action"{assert!(v["error"].is_null(),"{}",v["error"]);assert!(v["result"]["contents"].as_str().unwrap().len()>100)}if kind=="document-frame"{assert!(v["error"].is_null(),"{}",v["error"]);frames+=1;if first.is_empty(){first=v["url"].as_str().unwrap().to_string();manager.send(json!({"op":"document-input","requestId":id,"event":{"type":"resize","width":740,"height":420}}));}else if v["width"]==740&&v["height"]==420{resized=true;break}}}
 assert!(resized);let path=reqwest::Url::parse(&first).unwrap().to_file_path().unwrap();let dir=path.parent().unwrap().to_owned();manager.send(json!({"op":"document-close"}));for _ in 0..100{if !dir.exists(){break}std::thread::sleep(std::time::Duration::from_millis(30))}assert!(!dir.exists(),"private frame directory cleaned on close");println!("EMBEDDED_DOCUMENT_PASS remote file, {frames} frames, resize, no visible window, cleanup");
}
